import{_ as e,c as t,o as i,aj as r}from"./chunks/framework.CDhdelVI.js";const u=JSON.parse('{"title":"Roman Pizza al Taglio (High Hydration)","description":"A high-hydration Roman tray pizza with an ultra-light interior and a crackly, crisp bottom.","frontmatter":{"title":"Roman Pizza al Taglio (High Hydration)","description":"A high-hydration Roman tray pizza with an ultra-light interior and a crackly, crisp bottom.","head":[["meta",{"name":"description","content":"A high-hydration Roman tray pizza with an ultra-light interior and a crackly, crisp bottom."}],["meta",{"property":"og:title","content":"Roman Pizza al Taglio (High Hydration)"}],["meta",{"property":"og:description","content":"A high-hydration Roman tray pizza with an ultra-light interior and a crackly, crisp bottom."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:url","content":"https://kitchenratio.com/recipes/roman-al-taglio-pizza.html"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Roman Pizza al Taglio (High Hydration)"}],["meta",{"name":"twitter:description","content":"A high-hydration Roman tray pizza with an ultra-light interior and a crackly, crisp bottom."}],["link",{"rel":"canonical","href":"https://kitchenratio.com/recipes/roman-al-taglio-pizza.html"}]]},"headers":[],"relativePath":"recipes/roman-al-taglio-pizza.md","filePath":"recipes/roman-al-taglio-pizza.md"}'),l={name:"recipes/roman-al-taglio-pizza.md"};function n(o,a,s,h,d,g){return i(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="roman-pizza-al-taglio-high-hydration" tabindex="-1">Roman Pizza al Taglio (High Hydration) <a class="header-anchor" href="#roman-pizza-al-taglio-high-hydration" aria-label="Permalink to “Roman Pizza al Taglio (High Hydration)”">​</a></h1><p>This dough is wet on purpose. The goal is an airy interior with a thin, crisp shell that fractures when you bite it. Handle it gently, give it time, and let the pan and heat do the heavy lifting. Use the <a href="https://kitchenratio.com/calculator" target="_blank" rel="noreferrer">KitchenRatio Calculator</a> to scale any batch size.</p><div class="info custom-block"><p class="custom-block-title">Testing Status</p><p>This formula is still being tested and refined.</p></div><h2 id="baker-s-testing-range" tabindex="-1">Baker&#39;s % (Testing Range) <a class="header-anchor" href="#baker-s-testing-range" aria-label="Permalink to “Baker&#39;s % (Testing Range)”">​</a></h2><ul><li><strong>Flour</strong> - 100%</li><li><strong>Water</strong> - 78-82%</li><li><strong>Salt</strong> - 2-2.5%</li><li><strong>Olive oil</strong> - 1-2%</li><li><strong>Sugar</strong> - 0-1%</li><li><strong>Yeast (IDY)</strong> - 0.1-0.3%</li></ul><h2 id="ingredients-example-batch" tabindex="-1">Ingredients (Example Batch) <a class="header-anchor" href="#ingredients-example-batch" aria-label="Permalink to “Ingredients (Example Batch)”">​</a></h2><ul><li><strong>Flour</strong> - 500g (100%)</li><li><strong>Water</strong> - 400g (80%)</li><li><strong>Salt</strong> - 11g (2.2%)</li><li><strong>Olive oil</strong> - 7.5g (1.5%)</li><li><strong>Sugar</strong> - 2.5g (0.5%)</li><li><strong>Instant dry yeast</strong> - 1g (0.2%)</li></ul><p>Need a scale? <a href="https://amzn.to/48F9DfT" target="_blank" rel="noreferrer">KitchenAid Digital Scale</a>.</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>This batch works well for one 10x14-inch tray or similar surface area.</p></div><hr><h2 id="procedure" tabindex="-1">Procedure <a class="header-anchor" href="#procedure" aria-label="Permalink to “Procedure”">​</a></h2><h3 id="_1-gentle-mix" tabindex="-1">1. Gentle Mix <a class="header-anchor" href="#_1-gentle-mix" aria-label="Permalink to “1. Gentle Mix”">​</a></h3><ul><li>Combine flour, yeast, sugar, and about 90% of the water.</li><li>Mix until no dry flour remains and rest 15 minutes.</li><li>Add salt, oil, and remaining water gradually.</li><li>Mix only until smooth and cohesive. Do not aggressively knead.</li></ul><h3 id="_2-strength-through-folds" tabindex="-1">2. Strength Through Folds <a class="header-anchor" href="#_2-strength-through-folds" aria-label="Permalink to “2. Strength Through Folds”">​</a></h3><ul><li>Rest 20-30 minutes, then perform first fold.</li><li>Repeat for <strong>2-3 folds total</strong> during the first 90 minutes.</li><li>Dough should gain structure while staying soft and mobile.</li></ul><h3 id="_3-cold-fermentation" tabindex="-1">3. Cold Fermentation <a class="header-anchor" href="#_3-cold-fermentation" aria-label="Permalink to “3. Cold Fermentation”">​</a></h3><ul><li>Cover and refrigerate for <strong>24-72 hours</strong>.</li><li>Longer cold time improves extensibility and flavor.</li></ul><h3 id="_4-warm-and-pan" tabindex="-1">4. Warm and Pan <a class="header-anchor" href="#_4-warm-and-pan" aria-label="Permalink to “4. Warm and Pan”">​</a></h3><ul><li>Remove dough 1.5-2.5 hours before bake.</li><li>Oil tray well.</li><li>Transfer dough and stretch gently with oiled hands.</li><li>If it fights back, rest 10 minutes and continue.</li></ul><h3 id="_5-final-proof-in-pan" tabindex="-1">5. Final Proof in Pan <a class="header-anchor" href="#_5-final-proof-in-pan" aria-label="Permalink to “5. Final Proof in Pan”">​</a></h3><ul><li>Proof until visibly airy and jiggly, usually <strong>1.5-3 hours</strong> depending on room temp.</li><li>Dimple lightly to even thickness without crushing the structure.</li></ul><h3 id="_6-optional-parbake-path" tabindex="-1">6. Optional Parbake Path <a class="header-anchor" href="#_6-optional-parbake-path" aria-label="Permalink to “6. Optional Parbake Path”">​</a></h3><ul><li>Parbake at <strong>500-550F</strong> for <strong>5-8 minutes</strong> if you want a stronger base before topping.</li><li>Cool briefly, top, then finish bake.</li></ul><h3 id="_7-final-bake" tabindex="-1">7. Final Bake <a class="header-anchor" href="#_7-final-bake" aria-label="Permalink to “7. Final Bake”">​</a></h3><ul><li>Bake at <strong>500-550F</strong> until bottom is crisp and top is well set.</li><li>Total bake is usually <strong>10-16 minutes</strong> depending on whether you parbake.</li></ul><h3 id="_8-cool-and-cut" tabindex="-1">8. Cool and Cut <a class="header-anchor" href="#_8-cool-and-cut" aria-label="Permalink to “8. Cool and Cut”">​</a></h3><ul><li>Rest on a rack for 3-5 minutes.</li><li>Slice into squares or strips.</li></ul><h2 id="handling-rules-that-matter" tabindex="-1">Handling Rules That Matter <a class="header-anchor" href="#handling-rules-that-matter" aria-label="Permalink to “Handling Rules That Matter”">​</a></h2><ul><li>Keep hands and tools lightly oiled when moving dough.</li><li>Skip extra bench flour where possible; it can dull bottom crispness.</li><li>If dough looks loose, fold and wait. Do not rush to add flour.</li></ul><h2 id="what-to-adjust-first" tabindex="-1">What to Adjust First <a class="header-anchor" href="#what-to-adjust-first" aria-label="Permalink to “What to Adjust First”">​</a></h2><ul><li><strong>Too dense</strong>: increase hydration by 1-2% or extend pan proof.</li><li><strong>Too hard to handle</strong>: drop hydration to 78-79% while process is dialed in.</li><li><strong>Pale bottom</strong>: longer preheat and lower rack placement.</li></ul><h2 id="related-guides" tabindex="-1">Related Guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to “Related Guides”">​</a></h2><ul><li><a href="/guides/hydration.html">Hydration</a></li><li><a href="/guides/fermentation.html">Fermentation</a></li><li><a href="/guides/folding.html">Folding</a></li></ul><h2 id="get-the-gear" tabindex="-1">Get the Gear <a class="header-anchor" href="#get-the-gear" aria-label="Permalink to “Get the Gear”">​</a></h2><ul><li><a href="/guides/baking-gear-and-ingredients.html">Baking Gear &amp; Ingredients</a></li></ul><h2 id="related-recipes" tabindex="-1">Related Recipes <a class="header-anchor" href="#related-recipes" aria-label="Permalink to “Related Recipes”">​</a></h2><ul><li><a href="/recipes/new-york-style-pizza.html">New York Style Pizza (Home-Oven Optimized)</a></li><li><a href="/recipes/cold-iron-cloud-pan-pizza.html">Cold Iron Cloud Pan Pizza</a></li></ul><hr><blockquote><p><strong>Affiliate Disclaimer</strong> This post contains affiliate links. As an Amazon Associate, I earn from qualifying purchases. If you click on a link and make a purchase, I may receive a small commission at no extra cost to you.</p></blockquote>',39)])])}const m=e(l,[["render",n]]);export{u as __pageData,m as default};
